package com.example.dsatracker.service;import com.example.dsatracker.dto.UserRequestDTO;import com.example.dsatracker.dto.UserResponseDTO;import com.example.dsatracker.model.User;import com.example.dsatracker.mapper.UserMapper;import com.example.dsatracker.repository.UserRepository;import org.springframework.stereotype.Service;@Servicepublic class UserService {    private final UserRepository repository;    public UserService(UserRepository repository) {        this.repository = repository;    }    public UserResponseDTO createUser(UserRequestDTO request) {        User user = UserMapper.toEntity(request);        User savedUser = repository.save(user);        return UserMapper.toResponse(savedUser);    }}